/* @socom-skeleton stub SetTimeScale__10CZBodyAnimFf */
void CZBodyAnim::SetTimeScale(float scale)
{
	/* 0x1e1b00: a looped anim scales by its multiplier */
	if (m_looped)
		scale *= m_multiplier;

	m_tScale = scale;
}

